206	    ```csharp
207	    using System.Data;
208	    using Microsoft.EntityFrameworkCore;
209	    using seed_b_backend.Api.Data;
210	    using seed_b_backend.Api.Domain;
211	
212	    namespace seed_b_backend.Api.Application;
213	
214	    public class OrderService(AppDbContext context)
215	    {
216	        public async Task<OrderPlacementResult> PlaceOrderAsync(
217	            Guid? cartId,
218	            string customerName,
219	            string deliveryAddress,
220	            string email,
221	            CancellationToken ct = default)
222	        {
223	            if (cartId is null)
224	            {
225	                return new OrderPlacementResult { Status = OrderPlacementStatus.CartEmpty };
226	            }
227	
228	            var lines = await context.CartItems
229	                .Where(ci => ci.CartId == cartId)
230	                .Select(ci => new { ci.ProductId, ci.SupplierId, ci.Quantity })
231	                .ToListAsync(ct);
232	
233	            if (lines.Count == 0)
234	            {
235	                return new OrderPlacementResult { Status = OrderPlacementStatus.CartEmpty };
236	            }
237	
238	            var invalidQuantityLines = lines
239	                .Where(l => l.Quantity < 1)
240	                .Select(l => new OrderLineRejection
241	                {
242	                    ProductId = l.ProductId,
243	                    SupplierId = l.SupplierId,
244	                    Reason = OrderLineRejectionReason.InvalidQuantity
245	                })
246	                .ToList();
247	            if (invalidQuantityLines.Count > 0)
248	            {
249	                return new OrderPlacementResult { Status = OrderPlacementStatus.LinesRejected, RejectedLines = invalidQuantityLines };
250	            }
251	
252	            await using var transaction = await context.Database.BeginTransactionAsync(IsolationLevel.Serializable, ct);
253	
254	            var offerPrices = new Dictionary<(string ProductId, string SupplierId), decimal>();
255	            var offerGoneLines = new List<OrderLineRejection>();
256	            foreach (var line in lines)
257	            {
258	                var price = await context.Offers
259	                    .Where(o => o.ProductId == line.ProductId && o.SupplierId == line.SupplierId)
260	                    .Select(o => (decimal?)o.Price)
261	                    .SingleOrDefaultAsync(ct);
262	
263	                if (price is null)
264	                {
265	                    offerGoneLines.Add(new OrderLineRejection
266	                    {
267	                        ProductId = line.ProductId,
268	                        SupplierId = line.SupplierId,
269	                        Reason = OrderLineRejectionReason.OfferGone
270	                    });
271	                }
272	                else
273	                {
274	                    offerPrices[(line.ProductId, line.SupplierId)] = price.Value;
275	                }
276	            }
277	
278	            if (offerGoneLines.Count > 0)
279	            {
280	                await transaction.RollbackAsync(ct);
281	                return new OrderPlacementResult { Status = OrderPlacementStatus.LinesRejected, RejectedLines = offerGoneLines };
282	            }
283	
284	            var order = new Order
285	            {
286	                Id = Guid.NewGuid(),
287	                CustomerName = customerName,
288	                DeliveryAddress = deliveryAddress,
289	                Email = email
290	            };
291	            context.Orders.Add(order);
292	
293	            foreach (var line in lines)
294	            {
295	                context.OrderItems.Add(new OrderItem
296	                {
297	                    OrderId = order.Id,
298	                    ProductId = line.ProductId,
299	                    SupplierId = line.SupplierId,
300	                    Quantity = line.Quantity,
301	                    UnitPrice = offerPrices[(line.ProductId, line.SupplierId)]
302	                });
303	            }
304	
305	            await context.SaveChangesAsync(ct);
306	            await context.CartItems.Where(ci => ci.CartId == cartId).ExecuteDeleteAsync(ct);
307	            await transaction.CommitAsync(ct);
308	
309	            return new OrderPlacementResult
310	            {
311	                Status = OrderPlacementStatus.Success,
312	                Order = await BuildOrderResultAsync(order.Id, ct)
313	            };
314	        }
315	
316	        private async Task<OrderResult> BuildOrderResultAsync(Guid orderId, CancellationToken ct)
317	        {
318	            var order = await context.Orders.SingleAsync(o => o.Id == orderId, ct);
319	            var lines = await context.OrderItems
320	                .Where(oi => oi.OrderId == orderId)
321	                .Select(oi => new OrderResultLine
322	                {
323	                    ProductId = oi.ProductId,
324	                    ProductName = oi.Product!.Name,
325	                    SupplierId = oi.SupplierId,
326	                    SupplierName = oi.Supplier!.Name,
327	                    Quantity = oi.Quantity,
328	                    UnitPrice = oi.UnitPrice
329	                })
330	                .ToListAsync(ct);
331	
332	            return new OrderResult
333	            {
334	                OrderId = order.Id,
335	                Status = order.Status,
336	                Items = lines,
337	                TotalPrice = lines.Sum(l => l.UnitPrice * l.Quantity)
338	            };
339	        }
340	    }
341	    ```
342	    - **Prüfreihenfolge ist bewusst und nicht vertauschbar (AC 3 vs. AC 4):** Leerer Warenkorb und unzulässige Menge werden **vor** `BeginTransactionAsync` per einfachem Read geprüft (AD-3: „Before opening a transaction, order placement rejects immediately if the cart has zero lines or any line has an invalid quantity"); die `Offer`-Existenz wird **erst danach**, innerhalb der sperrenden Transaktion, geprüft (AD-3: „re-reads exactly the Offer rows … using a locking/serializable read"). **Konsequenz, nicht Fehler:** Enthält ein Warenkorb gleichzeitig eine Zeile mit unzulässiger Menge UND eine Zeile mit entferntem Angebot, meldet die Antwort ausschließlich die Mengen-Verletzung(en) — der Angebots-Check läuft nie, weil die Methode vorher zurückkehrt. Das ist die von AD-3 vorgegebene Reihenfolge, keine unvollständige Fehlererkennung.
343	    - **Pro-Zeile-Query statt eines einzelnen `Contains`/`Contains`-Filters für die `Offer`-Lesung:** Ein naiver `Where(o => productIds.Contains(o.ProductId) && supplierIds.Contains(o.SupplierId))` würde bei mehreren Warenkorbzeilen ein falsches Kreuzprodukt matchen (z. B. träfe er bei Zeilen `(P1,S1)` und `(P2,S2)` fälschlich auch ein existierendes, aber nicht im Warenkorb befindliches Angebot `(P1,S2)`). Die Schleife mit `ProductId == line.ProductId && SupplierId == line.SupplierId` pro Zeile vermeidet diesen Fehler; mehrere kleine Queries innerhalb derselben `Serializable`-Transaktion sind bezüglich der Sperrsemantik äquivalent zu einer einzigen Batch-Query — jede gelesene Zeile wird unter `Serializable`-Isolationsebene bis zum Commit gesperrt/überwacht (identische Garantie wie ein `WITH (UPDLOCK, HOLDLOCK)`-Batch-Read), nur mit mehreren Round-Trips statt einem. Beim aktuellen kleinen Referenzdatenbestand unkritisch (NFR4-Platzhalter).
344	    - **`IsolationLevel.Serializable` statt roher `WITH (UPDLOCK, HOLDLOCK)`-SQL-Hints:** AD-3 nennt beide Optionen explizit gleichwertig („e.g. a locking read such as `WITH (UPDLOCK, HOLDLOCK)`, or `IsolationLevel.Serializable`"); `IsolationLevel.Serializable` ist provider-neutral (funktioniert identisch gegen SQL Server in Produktion und SQLite in Tests, siehe Task 3), während rohe T-SQL-Hints nur gegen SQL Server liefen und die bestehende SQLite-Testinfrastruktur (Story 1.1–3.2) gebrochen hätten.
345	    - **`ExecuteDeleteAsync` auf `CartItems` läuft innerhalb derselben Transaktion wie `Order`/`OrderItem`, nicht danach:** Die PRD formuliert „wird der Warenkorb im Anschluss vollständig geleert" (zeitlich nach der Bestellanlage), aber AD-3 fordert nur explizit Atomarität für `Order`+`OrderItem`. Diese Story geht bewusst einen Schritt weiter und schließt das Leeren in dieselbe Transaktion ein — verhindert einen Zwischenzustand, in dem eine Bestellung bereits committet, der Warenkorb aber (z. B. durch einen Absturz zwischen den beiden Schritten) noch mit denselben, jetzt bereits bestellten Positionen gefüllt ist. Kein AD-3-Verstoß (stärkere, nicht schwächere Garantie), konsistent mit dem Prinzip „das System muss Ende-zu-Ende funktionsfähig bleiben, nicht nur die wörtlichen ACs erfüllen".
346	    - **`CartId`-Feld/`Cart`-Zeile selbst wird nicht gelöscht, nur die `CartItem`-Zeilen:** „Warenkorb wird geleert" (PRD) bedeutet 0 Positionen, nicht Löschung des `Cart`-Datensatzes — identische Cart-Identität (`X-Cart-Id`) bleibt für den Gast gültig und liefert danach über `GET /api/cart` (Story 3.2) korrekt einen leeren Warenkorb zurück, kein neuer Header-Wert nötig.
347	    - **Kein `DbUpdateException`-Race-Fallback wie bei `CartService.AddItemAsync`/`RatingService.SubmitRatingAsync`:** Es gibt hier keinen App-seitigen Check-then-Insert-Unique-Constraint-Konflikt — `Order.Id`/`OrderItem`-Primärschlüssel werden serverseitig frisch generiert (`Guid.NewGuid()`), keine zwei gleichzeitigen Bestellabschlüsse können denselben `OrderId` treffen. Die einzige Race-Gefahr (konkurrierende Änderung an einem referenzierten `Offer`) wird bereits durch die `Serializable`-Transaktion selbst abgedeckt, kein zusätzlicher Fallback-Zweig nötig.
348	
349	- [x] **Task 3: DTOs und `OrdersController`** (AC: 1, 2, 3, 4, 5, 6)
350	  - [x] `seed-b-backend.Api/Controllers/Dtos/PlaceOrderRequest.cs` (NEU) — identisches Validierungsmuster wie `AddCartItemRequest` (Story 3.1):
351	    ```csharp
352	    using System.ComponentModel.DataAnnotations;
353	
354	    namespace seed_b_backend.Api.Controllers.Dtos;
355	
