                            Reason = l.Reason == OrderLineRejectionReason.InvalidQuantity
                                ? "unzulaessige_menge"
                                : "angebot_nicht_mehr_verfuegbar"
                        })
                        .ToList()
                }),
                _ => StatusCode(StatusCodes.Status201Created, MapToDto(result.Order!))
            };
